arguments.new_string:
# pruning: keep=3 in config/rotate.conf
for i in 3 4 5 6; do echo "r$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
[ "$(ls "$d/logs" | grep -c '^app.log\.[0-9]*$')" = 3 ] || { echo "local prune count"; fail=1; }
[ ! -e "$d/logs/app.log.4" ] || { echo "local app.log.4 remains"; fail=1; }
[ "$(ls "$d/archive")" = "$(printf 'app.log.20261004\napp.log.20261005\napp.log.20261006')" ] || { echo "archive prune"; ls "$d/archive"; fail=1; }
rm -rf "$d"
exit $fail

